def solve(inputs: dict) -> float:
    x = inputs['SEED']
    a = inputs['A']
    b = inputs['B']
    m = inputs['M']
    k = int(inputs['K'])

    # Apply the recurrence k times
    for _ in range(k):
        x = (a * x + b) % m

    return float(x)

