{"name": "factorial_mod", "code": "import math

def solve(inputs: dict) -> float:
    n = int(inputs['N'])
    mod = int(inputs['MOD'])

    # Compute n! mod m
    factorial = math.factorial(n)
    result = factorial % mod

    return float(result)
